import type { DailyDoseEntry } from '@/lib/daily-dose/types';

export const PT_DAILY_DOSE_PART_2: DailyDoseEntry[] = [
  {
    date: '2026-10-20',
    category: 'food',
    topic_summary: 'Rice and beans, the everyday plate in almost every Brazilian home, and how to compliment it at the table.',
    easy_target: `No Brasil, muita gente come arroz e feijão todos os dias. Eu adoro arroz e feijão!`,
    easy_english: `In Brazil, a lot of people eat rice and beans every day. I love rice and beans!`,
    medium_target: `O prato do dia a dia no Brasil é arroz com feijão. Muita gente come isso no almoço e no jantar, com carne, ovo ou salada. Na mesa, você coloca o feijão por cima do arroz e mistura tudo. Quando está bom, você diz: Que delícia! Depois, você pode pedir mais feijão, por favor.`,
    medium_english: `The everyday plate in Brazil is rice with beans. A lot of people eat it at lunch and at dinner, with meat, egg or salad. At the table, you put the beans on top of the rice and mix everything. When it is good, you say: How delicious! Afterwards, you can ask for more beans, please.`,
    hard_target: `Arroz e feijão é a base da comida de casa no Brasil. O feijão já era comida dos povos indígenas antes de os portugueses chegarem, e o arroz chegou depois. Hoje, muitas famílias comem os dois no almoço e no jantar, quase todos os dias. Nos restaurantes simples, existe o prato feito, um prato com arroz, feijão, carne e salada que custa pouco. Num almoço de família, vai ter muita coisa na mesa, mas o arroz e o feijão quase sempre estão lá. Quando você experimentar o feijão da casa, diga que está gostoso e elogie quem cozinhou. Repetir o prato também é um elogio, então ninguém vai se surpreender se você pedir mais.`,
    hard_english: `Rice and beans are the base of home cooking in Brazil. Beans were already food for the Indigenous peoples before the Portuguese arrived, and rice came later. Today, many families eat both at lunch and at dinner, almost every day. In simple restaurants, there is the prato feito, a plate with rice, beans, meat and salad that costs little. At a family lunch there will be a lot on the table, but rice and beans are almost always there. When you try the beans of the house, say they are tasty and compliment whoever cooked. Having seconds is also a compliment, so nobody will be surprised if you ask for more.`,
  },
  {
    date: '2026-10-21',
    category: 'weather',
    topic_summary: 'Small talk about the weather with the phrases "Que calor!", "Vai chover?" and "Está frio hoje", the safest way to start a conversation.',
    easy_target: `Que calor hoje, né? Você acha que vai chover à tarde ou vai ficar quente?`,
    easy_english: `It's so hot today, isn't it? Do you think it will rain this afternoon or stay hot?`,
    medium_target: `Falar do tempo é a forma mais fácil de começar uma conversa. Quando faz calor, as pessoas dizem "Que calor!" e, quando faz frio, dizem "Está frio hoje". Se o céu fica escuro, alguém pergunta: Vai chover? Você pode responder: Acho que sim, o céu está bem cinza. Assim a conversa começa, e ninguém fica sem assunto.`,
    medium_english: `Talking about the weather is the easiest way to start a conversation. When it is hot, people say "It's so hot!" and, when it is cold, they say "It's cold today". If the sky gets dark, someone asks: Will it rain? You can answer: I think so, the sky is very gray. This way the conversation starts, and nobody runs out of things to say.`,
    hard_target: `Falar do tempo é a forma mais fácil de começar uma conversa com qualquer pessoa no Brasil. Quando faz calor, todo mundo diz "Que calor!" e ninguém discorda. Se o céu escurece, alguém pergunta se vai chover, e você pode responder que acha que sim. Para falar do dia de hoje, use "Está frio hoje" ou "Está um sol lindo". Também dá para contar como foi o dia: Ontem estava muito quente, mas depois choveu. Para falar do futuro, use o verbo ir: Amanhã vai fazer sol, mas de tarde vai chover. Com essas frases simples, você já consegue conversar com quase todo mundo à mesa.`,
    hard_english: `Talking about the weather is the easiest way to start a conversation with anyone in Brazil. When it is hot, everybody says "It's so hot!" and nobody disagrees. If the sky darkens, someone asks whether it will rain, and you can answer that you think so. To talk about today, use "It's cold today" or "It's beautifully sunny". You can also tell how the day went: Yesterday it was very hot, but then it rained. To talk about the future, use the verb ir: Tomorrow it will be sunny, but in the afternoon it will rain. With these simple phrases, you can already chat with almost everyone at the table.`,
  },
  {
    date: '2026-10-22',
    category: 'city',
    topic_summary: 'Three São Paulo neighbourhoods: Liberdade (Japanese), Mooca (Italian) and Vila Madalena (bars and street art).',
    easy_target: `São Paulo é enorme e cada bairro é diferente. A Liberdade tem cultura japonesa, a Mooca tem história italiana e a Vila Madalena tem bares.`,
    easy_english: `São Paulo is huge and every neighborhood is different. Liberdade has Japanese culture, Mooca has Italian history and Vila Madalena has bars.`,
    medium_target: `Cada bairro de São Paulo tem uma personalidade. Na Liberdade, você encontra restaurantes japoneses e lojas cheias de coisas do Japão. A Mooca é conhecida pela história italiana e pelas cantinas. Já a Vila Madalena tem muitos bares, música e arte de rua. Quando alguém pergunta aonde a gente vai, você já tem três ideias.`,
    medium_english: `Every neighborhood in São Paulo has its own personality. In Liberdade, you find Japanese restaurants and shops full of things from Japan. Mooca is known for its Italian history and its cantinas. Vila Madalena, on the other hand, has many bars, music and street art. When someone asks where we are going, you already have three ideas.`,
    hard_target: `São Paulo é uma cidade enorme, e cada bairro conta uma história diferente. A Liberdade ficou conhecida pela cultura japonesa porque muitas famílias de imigrantes japoneses se instalaram lá no século vinte. Hoje, o bairro tem restaurantes, lojas e uma feira nos fins de semana. A Mooca era um bairro de fábricas, e muitos italianos chegaram lá no fim do século dezenove para trabalhar, por isso ainda tem cantinas tradicionais. A Vila Madalena, por outro lado, é o bairro dos bares e da arte de rua, com muito grafite no Beco do Batman. Para conhecer os três, você vai precisar de tempo, porque o trânsito é pesado. Pergunte à Dani qual é o bairro favorito dela e comece por ele.`,
    hard_english: `São Paulo is a huge city, and every neighborhood tells a different story. Liberdade became known for Japanese culture because many families of Japanese immigrants settled there in the twentieth century. Today, the neighborhood has restaurants, shops and a street fair on weekends. Mooca used to be a neighborhood of factories, and many Italians arrived there in the late nineteenth century to work, which is why it still has traditional cantinas. Vila Madalena, on the other hand, is the neighborhood of bars and street art, with lots of graffiti in Beco do Batman. To see all three, you will need time, because the traffic is heavy. Ask Dani what her favorite neighborhood is and start with that one.`,
  },
  {
    date: '2026-10-23',
    category: 'food',
    topic_summary: 'The feira, the street market, with pastel, caldo de cana and fruit sellers calling out their prices.',
    easy_target: `Na feira, eu quero um pastel e um caldo de cana, por favor. Quanto é?`,
    easy_english: `At the market, I want a pastel and a sugarcane juice, please. How much is it?`,
    medium_target: `A feira é um mercado de rua que acontece toda semana, em dias diferentes em cada bairro. Os feirantes gritam os preços: Olha a mexerica, tá docinha! Muita gente come um pastel quente e bebe caldo de cana, um suco doce feito de cana-de-açúcar. Para comprar, pergunte: Quanto é o quilo? E diga bom dia com um sorriso.`,
    medium_english: `The feira is a street market that happens every week, on different days in each neighborhood. The sellers shout their prices: Look at the tangerines, they're so sweet! Lots of people eat a hot pastel and drink caldo de cana, a sweet juice made from sugarcane. To buy something, ask: How much is a kilo? And say good morning with a smile.`,
    hard_target: `A feira livre é um mercado de rua que acontece em dias diferentes em cada bairro. De manhã cedo, os feirantes montam as barracas e organizam frutas, verduras e legumes. Quando você passa, eles gritam os preços: Olha a mexerica, três por cinco reais! Muitas vezes, o feirante deixa você provar uma fruta antes de comprar. Depois das compras, é comum comer um pastel quente, de queijo, carne ou palmito, e beber um caldo de cana gelado. No final da feira, na chamada xepa, os preços costumam cair, e muita gente só aparece nessa hora. Se o feirante perguntar o que você queria, responda: Eu queria meio quilo de mexerica, por favor.`,
    hard_english: `The feira livre is a street market that happens on different days in each neighborhood. Early in the morning, the sellers set up their stalls and arrange fruit, greens and vegetables. When you walk by, they shout their prices: Look at the tangerines, three for five reais! Often, the seller lets you taste a fruit before you buy it. After shopping, it is common to eat a hot pastel, with cheese, meat or heart of palm, and to drink an ice-cold caldo de cana. At the end of the market, in the so-called xepa, prices usually drop, and many people only show up then. If the seller asks what you wanted, answer: I would like half a kilo of tangerines, please.`,
  },
  {
    date: '2026-10-24',
    category: 'culture',
    topic_summary: 'Brazilian time: arriving a little late to a family party is normal, while arriving early is not.',
    easy_target: `A festa é às oito, mas eu vou chegar às oito e meia. Tudo bem?`,
    easy_english: `The party is at eight, but I am going to arrive at eight thirty. Is that okay?`,
    medium_target: `Numa festa de família no Brasil, chegar um pouco atrasado é normal. Se o convite diz oito horas, muita gente chega às oito e meia ou às nove. Chegar cedo demais pode ser ruim, porque a casa ainda não está pronta. Mas em reuniões de trabalho, a hora é a hora. Na dúvida, pergunte à Dani: A que horas a gente chega?`,
    medium_english: `At a family party in Brazil, arriving a little late is normal. If the invitation says eight o'clock, many people arrive at eight thirty or at nine. Arriving too early can be bad, because the house is not ready yet. But for work meetings, the time is the time. When in doubt, ask Dani: What time do we arrive?`,
    hard_target: `No Brasil, o horário de uma festa de família é mais um convite do que uma regra. Se a festa é às oito, muita gente só chega depois das oito e meia, e ninguém acha isso estranho. Isso acontece porque quem convida costuma precisar desses minutos a mais para terminar a comida e se arrumar. Se você chegar cedo demais, pode encontrar o anfitrião ainda na cozinha, sem tempo para conversar. Imagine que o convite era para as oito e você chegou às oito e quinze: ninguém ia notar. Mas em reuniões de trabalho e no aeroporto, a hora marcada é para valer. Na dúvida, pergunte à Dani a que horas a família costuma chegar.`,
    hard_english: `In Brazil, the time of a family party is more of an invitation than a rule. If the party is at eight, many people only arrive after eight thirty, and nobody finds that strange. This happens because whoever invites usually needs those extra minutes to finish the food and get ready. If you arrive too early, you may find the host still in the kitchen, with no time to talk. Imagine the invitation was for eight and you arrived at eight fifteen: nobody would notice. But in work meetings and at the airport, the scheduled time is for real. When in doubt, ask Dani what time the family usually arrives.`,
  },
  {
    date: '2026-10-25',
    category: 'family',
    topic_summary: 'Showing photos on your phone and introducing your own family with "Esta é a minha mãe" and "Este é o meu irmão".',
    easy_target: `Olha as fotos no meu celular! Esta é a minha mãe e este é o meu irmão.`,
    easy_english: `Look at the photos on my phone! This is my mother and this is my brother.`,
    medium_target: `Mostrar fotos no celular é um jeito ótimo de falar da sua família. Para uma mulher, use esta, como em esta é a minha mãe; para um homem, use este, como em este é o meu irmão. Depois, alguém vai perguntar: E quem é essa? Você responde com o nome e diz como a pessoa é. Assim, todo mundo conhece a sua família.`,
    medium_english: `Showing photos on your phone is a great way to talk about your family. For a woman, use esta, as in "this is my mother"; for a man, use este, as in "this is my brother". Afterwards, someone will ask: And who is that? You answer with the name and say what the person is like. This way, everybody gets to know your family.`,
    hard_target: `Quando as pessoas se conhecem, é muito comum pegar o celular e mostrar fotos da família. Lembre que esta vai com palavras femininas, como mãe e irmã, e este vai com palavras masculinas, como pai e irmão. A Dona Márcia e o Seu Roberto provavelmente vão querer saber quem é quem, e vão fazer muitas perguntas. Por exemplo, eles podem perguntar onde a foto foi tirada e quantos anos a pessoa tinha. Você pode responder: Foi no aniversário dela, e todo mundo estava feliz. Eles também vão mostrar fotos da família deles, e você pode elogiar: Que foto linda! Assim, a conversa que começou com uma foto logo vira uma história longa e cheia de risadas.`,
    hard_english: `When people meet, it is very common to take out your phone and show photos of the family. Remember that esta goes with feminine words, like mother and sister, and este goes with masculine words, like father and brother. Dona Márcia and Seu Roberto will probably want to know who is who, and they will ask a lot of questions. For example, they may ask where the photo was taken and how old the person was. You can answer: It was at her birthday, and everybody was happy. They will also show photos of their own family, and you can compliment them: What a lovely photo! This way, the conversation that started with one photo soon becomes a long story full of laughter.`,
  },
  {
    date: '2026-10-26',
    category: 'city',
    topic_summary: 'Getting around São Paulo by metro, bus and Uber, and the famous traffic (trânsito).',
    easy_target: `Eu vou de metrô, porque o trânsito em São Paulo é muito grande. Você vai de ônibus ou de Uber?`,
    easy_english: `I am going by metro, because the traffic in São Paulo is huge. Are you going by bus or by Uber?`,
    medium_target: `Em São Paulo, muita gente anda de metrô, de ônibus ou de Uber. O metrô é rápido e não fica preso no trânsito, mas fica lotado no horário de pico. O trânsito da cidade é famoso, e uma viagem de carro pode demorar muito. Por isso, quando você tem pressa, o metrô costuma ser melhor. Na dúvida, pergunte: Qual é o caminho mais rápido?`,
    medium_english: `In São Paulo, a lot of people get around by metro, by bus or by Uber. The metro is fast and does not get stuck in traffic, but it gets packed at rush hour. The city's traffic is famous, and a trip by car can take a very long time. So, when you are in a hurry, the metro is usually better. When in doubt, ask: What is the fastest way?`,
    hard_target: `São Paulo é tão grande que ir de um bairro a outro pode parecer uma viagem. O metrô e os trens levam milhões de pessoas por dia e evitam o trânsito. Quando o primeiro trecho do metrô abriu, nos anos setenta, a cidade já era enorme, e a rede cresceu muito desde então. Os ônibus chegam a quase todos os bairros, mas ficam parados quando o trânsito piora. Muita gente também usa aplicativos, como o Uber e o 99. O trânsito é tão famoso que existe até uma regra, o rodízio, que proíbe alguns carros de circular em certos dias. Por isso, é melhor sair com tempo, porque ninguém sabe quanto a viagem vai demorar.`,
    hard_english: `São Paulo is so big that going from one neighborhood to another can feel like a trip. The metro and the trains carry millions of people a day and avoid the traffic. When the first section of the metro opened, in the seventies, the city was already huge, and the network has grown a lot since then. Buses reach almost every neighborhood, but they stand still when the traffic gets worse. A lot of people also use apps, like Uber and 99. The traffic is so famous that there is even a rule, the rodízio, that bans some cars from driving on certain days. So it is better to leave with time to spare, because nobody knows how long the trip will take.`,
  },
  {
    date: '2026-10-27',
    category: 'weather',
    topic_summary: 'São Paulo\'s nickname "terra da garoa" (land of drizzle), and December summer with hot days and afternoon storms.',
    easy_target: `São Paulo é a terra da garoa. Em dezembro, faz calor e muitas vezes chove à tarde.`,
    easy_english: `São Paulo is the land of drizzle. In December it is hot, and it often rains in the afternoon.`,
    medium_target: `São Paulo tem um apelido: a terra da garoa. Garoa é uma chuva fina e leve, quase uma neblina. Em dezembro é verão no Brasil, então os dias são quentes. Muitas vezes o sol aparece de manhã e, à tarde, vem uma tempestade forte. Leve um guarda-chuva na bolsa e roupa leve na mala.`,
    medium_english: `São Paulo has a nickname: the land of drizzle. Drizzle is a fine, light rain, almost a mist. In December it is summer in Brazil, so the days are hot. Often the sun comes out in the morning and, in the afternoon, a strong storm arrives. Take an umbrella in your bag and light clothes in your suitcase.`,
    hard_target: `São Paulo ficou conhecida como a terra da garoa, uma chuva fina e leve que era muito comum na cidade. Ainda hoje, em dias frios e cinzentos, a garoa aparece. Em dezembro, porém, é verão no Brasil, e o calor é forte. Nessa época, o dia começa com sol, e no fim da tarde vem uma tempestade com trovões. Às vezes, as ruas alagam por causa da chuva forte, e o trânsito piora ainda mais. Quem já visitou a cidade no verão sabe que o céu azul pode virar cinza em meia hora. Por isso, leve sempre um guarda-chuva e não esqueça as roupas leves. Se você vir nuvens escuras, não se assuste: vai chover, mas logo vai passar.`,
    hard_english: `São Paulo became known as the land of drizzle, a fine, light rain that used to be very common in the city. Even today, on cold, gray days, the drizzle shows up. In December, however, it is summer in Brazil, and the heat is strong. At that time of year, the day starts with sun, and at the end of the afternoon a storm with thunder arrives. Sometimes the streets flood because of the heavy rain, and the traffic gets even worse. Anyone who has visited the city in summer knows that a blue sky can turn gray in half an hour. So always carry an umbrella and do not forget light clothes. If you see dark clouds, do not be alarmed: it will rain, but it will soon pass.`,
  },
  {
    date: '2026-10-28',
    category: 'language',
    topic_summary: 'Diminutives with -inho and -inha (cafezinho, pouquinho, rapidinho) and how they make speech warmer.',
    easy_target: `Dona Márcia, eu aceito um cafezinho, obrigado. Mas só um pouquinho de açúcar, por favor!`,
    easy_english: `Dona Márcia, I'll have a little coffee, thank you. But just a tiny bit of sugar, please!`,
    medium_target: `No Brasil, as pessoas usam muito as terminações inho e inha. Elas fazem a palavra parecer pequena e também mais carinhosa. Café vira cafezinho, pouco vira pouquinho e rápido vira rapidinho. Um cafezinho pode ser uma xícara pequena, mas também é um gesto de boas-vindas. Quando você usa inho ao pedir algo, seu pedido fica mais simpático.`,
    medium_english: `In Brazil, people use the endings inho and inha a lot. They make a word seem small and also more affectionate. Café becomes cafezinho, pouco becomes pouquinho and rápido becomes rapidinho. A cafezinho can be a small cup, but it is also a gesture of welcome. When you use inho while asking for something, your request becomes friendlier.`,
    hard_target: `Em português, é muito comum falar com diminutivos, que são palavras com o final inho ou inha. Elas nem sempre significam pequeno: muitas vezes só deixam a conversa mais carinhosa e mais suave. Por exemplo, cafezinho vem de café, pouquinho vem de pouco e rapidinho vem de rápido. Quando alguém oferece um cafezinho, normalmente é um convite para sentar e conversar, e não só uma bebida. Se alguém perguntar se você estava com fome, você pode responder: Um pouquinho, sim! E quando precisa de tempo, diga só um minutinho. Mas você não precisa usar inho em tudo: comece com as palavras que aprendeu agora. Com cafezinho, pouquinho e rapidinho, você já vai soar muito mais brasileiro.`,
    hard_english: `In Portuguese, it is very common to speak with diminutives, which are words ending in inho or inha. They do not always mean small: often they just make the conversation warmer and softer. For example, cafezinho comes from café, pouquinho comes from pouco and rapidinho comes from rápido. When someone offers you a cafezinho, it is usually an invitation to sit down and talk, not just a drink. If someone asks whether you were hungry, you can answer: A little bit, yes! And when you need time, just say one little minute. But you do not need to use inho on everything: start with the words you have just learned. With cafezinho, pouquinho and rapidinho, you will already sound much more Brazilian.`,
  },
  {
    date: '2026-10-29',
    category: 'food',
    topic_summary: 'Brigadeiro, the chocolate sweet at every Brazilian party, and how easy it is to make.',
    easy_target: `O brigadeiro é um doce de chocolate que aparece em toda festa brasileira. Eu quero mais um, por favor!`,
    easy_english: `Brigadeiro is a chocolate sweet that shows up at every Brazilian party. I want one more, please!`,
    medium_target: `O brigadeiro é o doce de festa mais famoso do Brasil. Para fazer, você precisa de leite condensado, chocolate em pó e manteiga. Você mistura tudo numa panela e mexe até o doce desgrudar do fundo. Depois, faz bolinhas com as mãos e passa no granulado de chocolate. É fácil, e as crianças adoram ajudar.`,
    medium_english: `Brigadeiro is the most famous party sweet in Brazil. To make it, you need condensed milk, chocolate powder and butter. You mix everything in a pan and stir until the sweet pulls away from the bottom. Then you make little balls with your hands and roll them in chocolate sprinkles. It is easy, and children love to help.`,
    hard_target: `O brigadeiro é um doce de chocolate presente em quase toda festa de aniversário. Segundo a história mais conhecida, ele nasceu nos anos quarenta e ganhou o nome do brigadeiro Eduardo Gomes, que era candidato a presidente. Naquela época, a receita era simples, e hoje ela continua quase igual. Para fazer, você precisa de leite condensado, chocolate em pó e manteiga. Você mistura tudo numa panela e mexe sem parar, em fogo baixo, até desgrudar do fundo. Depois de esfriar, você passa manteiga nas mãos, enrola bolinhas e cobre com granulado de chocolate. Nas festas, ele fica na mesa ao lado do bolo e desaparece rápido. Se alguém oferecer um brigadeiro, aceite e diga que está uma delícia.`,
    hard_english: `Brigadeiro is a chocolate sweet found at almost every birthday party. According to the best-known story, it was born in the forties and got its name from Brigadeiro Eduardo Gomes, who was a presidential candidate. Back then, the recipe was simple, and today it is still almost the same. To make it, you need condensed milk, chocolate powder and butter. You mix everything in a pan and stir non-stop, over low heat, until it pulls away from the bottom. After it cools, you put butter on your hands, roll little balls and cover them with chocolate sprinkles. At parties, it sits on the table next to the cake and disappears fast. If someone offers you a brigadeiro, accept it and say it is delicious.`,
  },
  {
    date: '2026-10-30',
    category: 'culture',
    topic_summary: 'Brazilian birthday parties: singing "Parabéns pra você", clapping, and who gets the first slice of cake.',
    easy_target: `Na festa, todo mundo canta Parabéns pra você e bate palmas. Eu digo: Feliz aniversário!`,
    easy_english: `At the party, everybody sings "Happy Birthday" and claps. I say: Happy birthday!`,
    medium_target: `Nas festas de aniversário no Brasil, todo mundo se reúne em volta do bolo. A gente canta Parabéns pra você e bate palmas no ritmo da música. Depois, a pessoa faz um pedido e sopra a vela. Quando o bolo é cortado, o primeiro pedaço costuma ir para alguém muito especial. Você dá um abraço e diz: Parabéns!`,
    medium_english: `At birthday parties in Brazil, everybody gathers around the cake. We sing "Happy Birthday" and clap along to the rhythm of the song. Then the person makes a wish and blows out the candle. When the cake is cut, the first slice usually goes to someone very special. You give a hug and say: Congratulations!`,
    hard_target: `Numa festa de aniversário no Brasil, a hora mais importante é a do parabéns. Os convidados, que estavam conversando pela casa, se juntam em volta da mesa e cantam Parabéns pra você, batendo palmas no ritmo. Depois, o aniversariante faz um pedido, sopra a vela e todo mundo canta uma cantiga que termina com rá-tim-bum. O primeiro pedaço de bolo é um gesto de carinho: o aniversariante escolhe uma pessoa querida e entrega o prato a ela. Se você esqueceu de levar um presente, não se preocupe, porque um abraço sincero já vale muito. Na hora do parabéns, ninguém vai reparar se você errar a letra: é só bater palmas e sorrir. Depois, todo mundo come bolo, brigadeiro e salgadinhos.`,
    hard_english: `At a birthday party in Brazil, the most important moment is the happy birthday song. The guests, who had been chatting around the house, gather around the table and sing "Happy Birthday", clapping along to the rhythm. Then the birthday person makes a wish, blows out the candle and everybody sings a little rhyme that ends with rá-tim-bum. The first slice of cake is a gesture of affection: the birthday person picks someone dear and hands them the plate. If you forgot to bring a present, do not worry, because a sincere hug is already worth a lot. When the song comes, nobody will notice if you get the words wrong: just clap and smile. After that, everybody eats cake, brigadeiro and savory snacks.`,
  },
  {
    date: '2026-10-31',
    category: 'culture',
    topic_summary: 'Halloween parties in Brazil on 31 October, and Dia do Saci, the day of the one-legged trickster of Brazilian folklore.',
    easy_target: `Em trinta e um de outubro, muita gente faz festa de Halloween. Mas também é o Dia do Saci, um menino de uma perna só.`,
    easy_english: `On the thirty-first of October, a lot of people have Halloween parties. But it is also the Day of the Saci, a boy with only one leg.`,
    medium_target: `No Brasil, muita gente faz festa de Halloween no dia trinta e um de outubro. Mas o país tem o seu próprio personagem assustador: o Saci. Ele é um menino travesso do folclore, com uma perna só e um gorro vermelho. O Saci faz travessuras, como esconder objetos e queimar o feijão. Quando a gente perde uma coisa, às vezes diz que foi o Saci!`,
    medium_english: `In Brazil, a lot of people have Halloween parties on the thirty-first of October. But the country has its own scary character: the Saci. He is a mischievous boy from folklore, with one leg and a red cap. The Saci plays pranks, like hiding objects and burning the beans. When we lose something, we sometimes say it was the Saci!`,
    hard_target: `Em trinta e um de outubro, muitos brasileiros fazem festas de Halloween, com fantasias, doces e decoração de abóbora. Mas nessa mesma data também se comemora o Dia do Saci, uma forma de valorizar o folclore brasileiro. O Saci é um menino travesso com uma perna só, um gorro vermelho e um cachimbo. Segundo a lenda, ele viaja dentro de redemoinhos de vento e adora esconder objetos, queimar o feijão e assustar os cavalos. O escritor Monteiro Lobato ajudou a tornar o Saci famoso quando escreveu livros para crianças. Antigamente, muitas crianças ouviam essas histórias antes de dormir, e tinham medo do assobio do Saci. Se alguém perder algo na festa, brinque e diga que foi o Saci.`,
    hard_english: `On the thirty-first of October, many Brazilians throw Halloween parties, with costumes, sweets and pumpkin decorations. But on that same date people also celebrate Saci Day, a way of valuing Brazilian folklore. The Saci is a mischievous boy with one leg, a red cap and a pipe. According to legend, he travels inside whirlwinds and loves to hide objects, burn the beans and scare the horses. The writer Monteiro Lobato helped make the Saci famous when he wrote books for children. In the old days, many children heard these stories before going to sleep, and they were afraid of the Saci's whistle. If someone loses something at the party, joke and say it was the Saci.`,
  },
  {
    date: '2026-11-01',
    category: 'small_talk',
    topic_summary: 'Talking about yourself: living in Bali, in Indonesia, and why that surprises people.',
    easy_target: `Eu moro em Bali, uma ilha na Indonésia. É muito longe do Brasil, mas eu vou visitar vocês!`,
    easy_english: `I live in Bali, an island in Indonesia. It is very far from Brazil, but I am going to visit you all!`,
    medium_target: `Quando eu digo que moro em Bali, muita gente faz cara de surpresa. Bali é uma ilha da Indonésia, um país da Ásia. As pessoas perguntam "Por que Bali?" e depois querem saber se é longe. Eu respondo que sim: a viagem até o Brasil é muito longa. Quando é meio-dia em São Paulo, já são onze da noite em Bali.`,
    medium_english: `When I say that I live in Bali, a lot of people look surprised. Bali is an island in Indonesia, a country in Asia. People ask "Why Bali?" and then want to know if it is far. I answer yes: the trip to Brazil is very long. When it is noon in São Paulo, it is already eleven at night in Bali.`,
    hard_target: `Quando você diz que mora em Bali, muita gente fica surpresa. Bali é uma ilha na Indonésia, um país enorme no Sudeste Asiático. As pessoas imaginam praias e arrozais, e a ilha é linda, mas lá também tem trabalho, trânsito e supermercado. O Brasil e Bali ficam muito longe um do outro, e a diferença de horário é de onze horas. Por isso, ligar para o Brasil exige um pouco de planejamento. Na mesa, a família vai perguntar por que você escolheu Bali e como era a sua vida antes de você se mudar para lá. Prepare uma resposta simples e sincera, sorria e conte a sua história devagar.`,
    hard_english: `When you say that you live in Bali, a lot of people are surprised. Bali is an island in Indonesia, a huge country in Southeast Asia. People imagine beaches and rice paddies, and the island is beautiful, but there is also work, traffic and supermarkets there. Brazil and Bali are very far from each other, and the time difference is eleven hours. So calling Brazil takes a little planning. At the table, the family will ask why you chose Bali and what your life was like before you moved there. Prepare a simple and sincere answer, smile and tell your story slowly.`,
  },
  {
    date: '2026-11-02',
    category: 'holidays',
    topic_summary: 'Finados on 2 November, a quiet holiday when families visit cemeteries and remember relatives.',
    easy_target: `Dois de novembro é o Dia de Finados. As famílias vão ao cemitério e lembram dos parentes que já morreram.`,
    easy_english: `The second of November is All Souls' Day. Families go to the cemetery and remember relatives who have died.`,
    medium_target: `Em dois de novembro, o Brasil tem um feriado calmo, o Dia de Finados. Nesse dia, muitas famílias visitam o cemitério e levam flores e velas. Elas lembram dos parentes e dos amigos que já morreram. Não é uma festa: o dia é tranquilo e um pouco triste, mas cheio de carinho. Se alguém contar que perdeu um parente, você pode dizer: Meus sentimentos.`,
    medium_english: `On the second of November, Brazil has a quiet holiday, All Souls' Day. On this day, many families visit the cemetery and bring flowers and candles. They remember relatives and friends who have died. It is not a party: the day is calm and a little sad, but full of affection. If someone tells you they lost a relative, you can say: My condolences.`,
    hard_target: `Em dois de novembro, o Brasil celebra o Dia de Finados, um feriado nacional. É uma tradição católica que existe há muitos séculos: um dia para lembrar quem já morreu. Diferente de outras datas, esse não é um dia de festa, e sim um dia calmo e sério. Muitas famílias vão ao cemitério durante o dia para limpar o túmulo, colocar flores e acender velas. Os cemitérios ficam cheios, e há vendedores de flores nas ruas ao redor. Nesse dia, muita gente conta histórias sobre os avós, lembrando como eles eram e o que diziam. Quando alguém disser que perdeu um parente, responda com respeito: Meus sentimentos. A palavra saudade, difícil de traduzir, resume bem o que as pessoas sentem.`,
    hard_english: `On the second of November, Brazil celebrates All Souls' Day, a national holiday. It is a Catholic tradition that has existed for many centuries: a day to remember those who have died. Unlike other dates, this is not a day for parties, but a calm and serious day. Many families go to the cemetery during the day to clean the grave, place flowers and light candles. The cemeteries fill up, and there are flower sellers on the streets around them. On this day, a lot of people tell stories about their grandparents, remembering what they were like and what they used to say. When someone tells you that they lost a relative, answer with respect: My condolences. The word saudade, hard to translate, sums up well what people feel.`,
  },
  {
    date: '2026-11-03',
    category: 'family',
    topic_summary: 'Talking about your own family: siblings, parents and where they live, in answer to the questions you will be asked.',
    easy_target: `Quando perguntam "Você tem irmãos?", você diz: Tenho um irmão, tenho uma irmã ou sou filho único.`,
    easy_english: `When they ask "Do you have siblings?", you say: I have a brother, I have a sister, or I am an only child.`,
    medium_target: `Perguntar sobre a família é normal no Brasil, e todo mundo gosta de conversar sobre isso. Você pode responder com frases curtas, como Tenho um irmão ou Tenho duas irmãs. Para falar dos pais, diga Meus pais moram em e o nome do lugar. Depois, alguém vai perguntar como eles são. Responda com um sorriso e faça a mesma pergunta para a família da Dani.`,
    medium_english: `Asking about the family is normal in Brazil, and everybody likes to talk about it. You can answer with short phrases, like I have a brother or I have two sisters. To talk about your parents, say "My parents live in" and the name of the place. Then someone will ask what they are like. Answer with a smile and ask Dani's family the same question.`,
    hard_target: `Na mesa de uma família brasileira, as perguntas sobre a sua família aparecem logo, porque as pessoas gostam de conhecer quem chega. A primeira pergunta quase sempre é: Você tem irmãos? Você pode responder Tenho um irmão, Tenho uma irmã ou Sou filho único, dependendo do seu caso. Para falar dos pais, diga Meus pais moram em e o nome da cidade. Também é comum perguntarem onde você morava quando era criança. Se você não sabe uma palavra, como sobrinho ou cunhado, mostre uma foto ou peça ajuda. Depois, faça as mesmas perguntas para eles, porque falar de família aproxima as pessoas. Você vai ver que a conversa que começou com irmãos e pais logo vira risada.`,
    hard_english: `At a Brazilian family's table, questions about your own family come up quickly, because people like to get to know whoever arrives. The first question is almost always: Do you have siblings? You can answer "I have a brother", "I have a sister" or "I am an only child", depending on your case. To talk about your parents, say "My parents live in" and the name of the city. It is also common for people to ask where you lived when you were a child. If you do not know a word, like nephew or brother-in-law, show a photo or ask for help. Then ask them the same questions, because talking about family brings people closer. You will see that a conversation that started with siblings and parents soon turns into laughter.`,
  },
  {
    date: '2026-11-04',
    category: 'small_talk',
    topic_summary: 'Answering "De onde você é?" and explaining that you are learning Portuguese.',
    easy_target: `Eu não sou daqui, mas estou aprendendo português. Falo um pouco, e falo devagar!`,
    easy_english: `I am not from here, but I am learning Portuguese. I speak a little, and I speak slowly!`,
    medium_target: `Uma pergunta que você vai ouvir muito é: De onde você é? Você responde eu sou de e o nome do país, ou usa a nacionalidade, como sou americano. Depois, muita gente pergunta: E onde você mora? Você pode dizer: Moro em Bali, na Indonésia, e estou aprendendo português. Isso faz as pessoas sorrirem e ajudarem você a falar.`,
    medium_english: `A question you will hear a lot is: Where are you from? You answer "I am from" and the name of the country, or you use your nationality, like "I am American". Afterwards, many people ask: And where do you live? You can say: I live in Bali, in Indonesia, and I am learning Portuguese. This makes people smile and help you to speak.`,
    hard_target: `Quando você conhecer a família da Dani, a primeira pergunta vai ser: De onde você é? Para responder, diga sou de e o nome do país, ou use a nacionalidade, como sou australiano. No masculino, a gente diz americano ou australiano, e no feminino, americana ou australiana. Depois, alguém vai perguntar onde você mora, e você responde: Moro em Bali, uma ilha na Indonésia. Também vão perguntar por que você começou a estudar português, e você pode responder: Comecei porque queria conversar com todo mundo. Se você não entender uma pergunta, diga: Pode repetir mais devagar, por favor? Muitos brasileiros adoram quando um estrangeiro tenta falar português, então o seu esforço vai ser bem recebido.`,
    hard_english: `When you meet Dani's family, the first question will be: Where are you from? To answer, say "I am from" and the name of the country, or use your nationality, like "I am Australian". In the masculine, we say americano or australiano, and in the feminine, americana or australiana. Afterwards, someone will ask where you live, and you answer: I live in Bali, an island in Indonesia. They will also ask why you started studying Portuguese, and you can answer: I started because I wanted to talk with everybody. If you do not understand a question, say: Could you repeat that more slowly, please? Many Brazilians love it when a foreigner tries to speak Portuguese, so your effort will be well received.`,
  },
  {
    date: '2026-11-05',
    category: 'language',
    topic_summary: 'Four everyday words you will hear at the table: Beleza, Valeu, Nossa and Legal.',
    easy_target: `Quatro palavras que você ouve muito: beleza, valeu, nossa e legal. Vamos usar as quatro!`,
    easy_english: `Four words you hear a lot: beleza, valeu, nossa and legal. Let's use all four!`,
    medium_target: `Na mesa de uma família brasileira, você vai ouvir quatro palavras o tempo todo. Beleza serve para perguntar como você está e também para responder que está tudo bem. Valeu é um jeito informal de dizer obrigado. Nossa mostra surpresa, e legal quer dizer que algo é bom ou bonito. Com os mais velhos, use obrigado em vez de valeu.`,
    medium_english: `At a Brazilian family's table, you will hear four words all the time. Beleza is used to ask how you are and also to answer that everything is fine. Valeu is an informal way of saying thank you. Nossa shows surprise, and legal means that something is good or nice. With older people, use obrigado instead of valeu.`,
    hard_target: `Palavras pequenas aparecem o tempo todo na mesa de uma família brasileira. A primeira é beleza, que serve para perguntar como você está e para responder que está tudo bem. A segunda é valeu, um jeito informal de agradecer entre amigos. A terceira é nossa, que vem de Nossa Senhora e hoje mostra surpresa, boa ou ruim. A quarta é legal, que serve para dizer que algo é bom, bonito ou interessante. Se alguém te contou uma novidade, responda: Nossa, que legal! Com pessoas mais velhas, como o Seu Roberto, obrigado é mais respeitoso do que valeu. E, se alguém perguntar como estava a viagem, você pode responder: Foi longa, mas valeu a pena!`,
    hard_english: `Small words appear all the time at a Brazilian family's table. The first is beleza, which is used to ask how you are and to answer that everything is fine. The second is valeu, an informal way of thanking people among friends. The third is nossa, which comes from Nossa Senhora and today shows surprise, good or bad. The fourth is legal, which is used to say that something is good, nice or interesting. If someone told you some news, answer: Wow, how cool! With older people, like Seu Roberto, obrigado is more respectful than valeu. And, if someone asks how the trip was, you can answer: It was long, but it was worth it!`,
  },
  {
    date: '2026-11-06',
    category: 'food',
    topic_summary: 'Churrasco, the Brazilian barbecue, picanha, and the churrasqueiro who runs the grill.',
    easy_target: `No churrasco, tem muita carne, e a picanha é a mais famosa. Eu quero um pedaço, por favor!`,
    easy_english: `At the churrasco, there is a lot of meat, and picanha is the most famous. I want a piece, please!`,
    medium_target: `Churrasco é o jeito brasileiro de fazer carne na brasa. A carne mais famosa é a picanha, macia e com uma camada de gordura. Quem cuida da grelha é o churrasqueiro, o rei da festa. Você pode dizer como quer a carne: ao ponto, mal passada ou bem passada. E não esqueça de elogiar o churrasqueiro: Que carne boa!`,
    medium_english: `Churrasco is the Brazilian way of cooking meat over embers. The most famous meat is picanha, tender and with a layer of fat. Whoever looks after the grill is the churrasqueiro, the king of the party. You can say how you want your meat: medium, rare or well done. And do not forget to compliment the churrasqueiro: What good meat!`,
    hard_target: `Churrasco é a carne assada na brasa, um programa muito comum de fim de semana com a família. Os cortes são grandes, geralmente temperados só com sal grosso, e assam devagar. A picanha é o corte mais famoso: macia, cheia de sabor e com uma capa de gordura que derrete na grelha. Antigamente, os gaúchos, no sul do país, faziam churrasco em espetos compridos, e essa tradição se espalhou pelo Brasil. Quem cuida da grelha é o churrasqueiro, que é tratado como o rei da festa. Ele vai perguntar como você quer a carne, e você pode responder: ao ponto, mal passada ou bem passada. Quando você quiser mais, diga mais um pedacinho, por favor, e elogie a picanha.`,
    hard_english: `Churrasco is meat roasted over embers, a very common weekend activity with the family. The cuts are big, usually seasoned only with coarse salt, and they roast slowly. Picanha is the most famous cut: tender, full of flavor and with a cap of fat that melts on the grill. In the old days, the gaúchos, in the south of the country, made churrasco on long skewers, and this tradition spread across Brazil. Whoever looks after the grill is the churrasqueiro, who is treated like the king of the party. He will ask how you want your meat, and you can answer: medium, rare or well done. When you want more, say one more little piece, please, and compliment the picanha.`,
  },
  {
    date: '2026-11-07',
    category: 'culture',
    topic_summary: 'At a family churrasco: farofa, vinagrete, garlic bread, and everyone standing around the grill talking.',
    easy_target: `Todo mundo fica em volta da grelha e conversa. Eu quero farofa, vinagrete e pão de alho, por favor!`,
    easy_english: `Everybody stands around the grill and talks. I want farofa, vinagrete and garlic bread, please!`,
    medium_target: `Num churrasco de família, as pessoas conversam em pé, perto da grelha, com um copo na mão. Junto com a carne, tem farofa, que é farinha de mandioca torrada com manteiga. Tem também vinagrete, uma salada de tomate, cebola e pimentão com vinagre. E o pão de alho fica dourado na grelha. Ofereça ajuda, perguntando: Posso ajudar?`,
    medium_english: `At a family churrasco, people talk standing up, near the grill, with a glass in hand. Along with the meat, there is farofa, which is cassava flour toasted with butter. There is also vinagrete, a salad of tomato, onion and bell pepper with vinegar. And the garlic bread turns golden on the grill. Offer to help by asking: Can I help?`,
    hard_target: `Se você chegou e o pessoal já estava em volta da grelha, é só se juntar à roda. Num churrasco de família, quase ninguém fica sentado: a graça é conversar em pé perto do fogo. Enquanto o churrasqueiro cuida da carne, os outros bebem alguma coisa, riem e contam histórias. Nas mesas, ficam os acompanhamentos, como arroz, farofa, vinagrete e pão de alho. A farofa é farinha de mandioca torrada na manteiga, e o vinagrete é uma salada de tomate, cebola e pimentão. O pão de alho vai para a grelha e sai crocante e dourado. Quando você já comeu o bastante, diga estou satisfeito, obrigado, mas alguém vai insistir para você comer só mais um pouquinho.`,
    hard_english: `If you arrived and the group was already around the grill, just join the circle. At a family churrasco, almost nobody sits: the fun is talking standing up near the fire. While the churrasqueiro looks after the meat, the others drink something, laugh and tell stories. On the tables are the side dishes, like rice, farofa, vinagrete and garlic bread. Farofa is cassava flour toasted in butter, and vinagrete is a salad of tomato, onion and bell pepper. The garlic bread goes on the grill and comes out crunchy and golden. When you have already eaten enough, say "I am full, thank you", but someone will insist that you eat just a little bit more.`,
  },
  {
    date: '2026-11-08',
    category: 'football',
    topic_summary: 'Football in São Paulo: Corinthians, Palmeiras, São Paulo and Santos, and the fact that every family has a team.',
    easy_target: `Em São Paulo, quase todo mundo tem um time: Corinthians, Palmeiras, São Paulo ou Santos. O futebol é muito importante!`,
    easy_english: `In São Paulo, almost everybody has a team: Corinthians, Palmeiras, São Paulo or Santos. Football is very important!`,
    medium_target: `Em São Paulo, o futebol é uma paixão de família. Os quatro times mais conhecidos são Corinthians, Palmeiras, São Paulo e Santos. Eles têm apelidos, como Timão para o Corinthians e Verdão para o Palmeiras. Muitas vezes, o time passa de pai para filho. Por isso, fale de futebol com respeito e com humor.`,
    medium_english: `In São Paulo, football is a family passion. The four best-known teams are Corinthians, Palmeiras, São Paulo and Santos. They have nicknames, like Timão for Corinthians and Verdão for Palmeiras. Often, the team is passed from father to child. So talk about football with respect and with humor.`,
    hard_target: `Em São Paulo, quase toda família tem um time, e o futebol é assunto de conversa em qualquer mesa. Os quatro grandes clubes do estado são o Corinthians, o Palmeiras, o São Paulo e o Santos. Os apelidos são Timão, Verdão, Tricolor e Peixe, nessa ordem. O Palmeiras foi fundado por imigrantes italianos no começo do século vinte, e no início se chamava Palestra Itália. O Santos ficou famoso no mundo todo porque o Pelé jogou lá quase a carreira inteira. Muitos torcedores herdaram o time do pai ou do avô, e trocar de time é quase uma traição. A pergunta mais comum é: Qual é o seu time?`,
    hard_english: `In São Paulo, almost every family has a team, and football is a topic of conversation at any table. The four big clubs of the state are Corinthians, Palmeiras, São Paulo and Santos. Their nicknames are Timão, Verdão, Tricolor and Peixe, in that order. Palmeiras was founded by Italian immigrants at the beginning of the twentieth century, and at first it was called Palestra Itália. Santos became famous all over the world because Pelé played there for almost his entire career. Many fans inherited their team from their father or grandfather, and switching teams is almost a betrayal. The most common question is: What is your team?`,
  },
  {
    date: '2026-11-09',
    category: 'football',
    topic_summary: 'Answering "Qual é o seu time?", the question you will surely be asked, with a friendly reply if you have no team.',
    easy_target: `Qual é o seu time? Ainda não tenho o meu, então me conte por que o seu é o melhor!`,
    easy_english: `What is your team? I don't have mine yet, so tell me why yours is the best!`,
    medium_target: `Em São Paulo, a pergunta mais comum sobre futebol é: Qual é o seu time? Se você tem um time, diga o nome dele. Se não tem, uma boa resposta é: Ainda não tenho time, mas estou escolhendo. Você também pode brincar e dizer que hoje torce pelo time de vocês. Todo mundo vai rir e explicar por que o time deles é o melhor.`,
    medium_english: `In São Paulo, the most common question about football is: What is your team? If you have a team, say its name. If you do not, a good answer is: I do not have a team yet, but I am choosing. You can also joke and say that today you are cheering for your hosts' team. Everybody will laugh and explain why their team is the best.`,
    hard_target: `No Brasil, quando o assunto é futebol, a pergunta mais comum é: Qual é o seu time? Não existe resposta certa, mas cuidado com as brincadeiras, porque a rivalidade é séria, mesmo entre amigos. Se você já tem um time, pode dizer o nome com sinceridade, mesmo que ele seja de outro país. Se ainda não tem, diga com um sorriso: Ainda não escolhi um time, mas estou aceitando sugestões. Outra saída simpática é dizer que hoje você torce pelo time da casa, e todo mundo vai rir. Se perguntarem por que você ainda não escolheu, diga que estava esperando conhecer a família antes de decidir. Ouça as histórias deles, porque cada torcedor tem um jogo inesquecível para contar.`,
    hard_english: `In Brazil, when the subject is football, the most common question is: What is your team? There is no right answer, but be careful with jokes, because the rivalry is serious, even among friends. If you already have a team, you can say its name sincerely, even if it is from another country. If you do not have one yet, say with a smile: I have not chosen a team yet, but I am accepting suggestions. Another friendly way out is to say that today you are cheering for the home team, and everybody will laugh. If they ask why you have not chosen yet, say that you were waiting to get to know the family before deciding. Listen to their stories, because every fan has an unforgettable match to tell about.`,
  },
];
